    function updateMain(slot, v) {
        console.log('[ArchetypeTab] update mainStats', archetype.id, slot, '→', v);
        const existing = ArchetypeStore.getArchetypes().find((a) => a.id === archetype.id);
        const ms = existing ? { ...(existing.mainStats || {}) } : {};
        ms[slot] = v;
        ArchetypeStore.updateArchetype(archetype.id, { mainStats: ms });
    }

    const necklaceVals = archetype.mainStats && archetype.mainStats.Necklace
        ? archetype.mainStats.Necklace.filter((x) => x !== null) : null;
    tr.appendChild(multiSelectTd(necklaceVals, KNOWN_NECKLACE, (v) => updateMain('Necklace', v)));

    const ringVals = archetype.mainStats && archetype.mainStats.Ring
        ? archetype.mainStats.Ring.filter((x) => x !== null) : null;
    tr.appendChild(multiSelectTd(ringVals, KNOWN_RING, (v) => updateMain('Ring', v)));

    const bootsVals = archetype.mainStats && archetype.mainStats.Boots
        ? archetype.mainStats.Boots.filter((x) => x !== null) : null;
    tr.appendChild(multiSelectTd(bootsVals, KNOWN_BOOTS, (v) => updateMain('Boots', v)));

